contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool doTransfer, address newOwner) public {
        require(newOwner != address(0), "newOwner must be nonzero");
        bool reverted1;
        bool reverted2;
        address ownerBefore = c.owner();
        try c.owned() { reverted1 = false; } catch { reverted1 = true; }
        bool isOwnerBefore = (ownerBefore == address(this));
        if (doTransfer && isOwnerBefore) {
            c.transferOwnership(newOwner);
        }
        address ownerMid = c.owner();
        try c.owned() { reverted2 = false; } catch { reverted2 = true; }
        address ownerAfter = c.owner();

        // General rule: if owned() succeeds, the caller was the current owner at call time.
        // Equivalently: a successful owned() call cannot happen for a non-owner caller.
        assert(reverted1 || isOwnerBefore);
        assert(reverted2 || ownerMid == address(this));

        // Ownership can only change via transferOwnership when caller is owner.
        if (doTransfer && isOwnerBefore) {
            assert(ownerAfter == newOwner);
        } else {
            assert(ownerAfter == ownerMid);
        }
    }
}

